export function applyReviewedCatalogueBatch03(byId: Map<string, Article>): void {
  for (const entry of REVIEWED_CATALOGUE_BATCH_03_TAGS) {
    const article = byId.get(entry.articleId);
    if (article && JSON.stringify(article.tags) === JSON.stringify(entry.previousTags)) article.tags = [...entry.tags];
  }
  applyContextualLinks(byId, REVIEWED_CATALOGUE_BATCH_03_LINKS);
}
